def compound_interest(principal: float, rate: float, compounds_per_year: int, years: int) -> tuple[float, float]:
    amount = principal * (1 + rate / compounds_per_year) ** (compounds_per_year * years)
    interest = amount - principal
    return round(amount, 2), round(interest, 2)

use std::time::Instant;

struct TokenBucket {
    capacity: f64,
    tokens: f64,
    rate: f64,
    last_refill: Instant,
}

impl TokenBucket {
    fn new(capacity: f64, rate: f64) -> Self {
        Self { capacity, tokens: capacity, rate, last_refill: Instant::now() }
    }
    fn try_consume(&mut self) -> bool {
        let now = Instant::now();
        let elapsed = now.duration_since(self.last_refill).as_secs_f64();
        self.tokens = (self.tokens + elapsed * self.rate).min(self.capacity);
        self.last_refill = now;
        if self.tokens >= 1.0 { self.tokens -= 1.0; true } else { false }
    }
}

import numpy as np

def sigmoid(x):
    return 1.0 / (1.0 + np.exp(-x))

def forward(x, weights, biases):
    for w, b in zip(weights, biases):
        x = sigmoid(x @ w + b)
    return x

