enum TempError { BelowAbsoluteZero }

fn celsius_to_fahrenheit(c: f64) -> Result<f64, TempError> {
    if c < -273.15 { return Err(TempError::BelowAbsoluteZero); }
    Ok(c * 9.0 / 5.0 + 32.0)
}

fn fahrenheit_to_celsius(f: f64) -> Result<f64, TempError> {
    if f < -459.67 { return Err(TempError::BelowAbsoluteZero); }
    Ok((f - 32.0) * 5.0 / 9.0)
}

